const OFFLINE_URL = 'pages/offline.html';

// Typed handle on the worker scope so the JSDoc typecheck knows the event types.
const sw = /** @type {ServiceWorkerGlobalScope} */ (/** @type {unknown} */ (self));

// Pure decision logic (which strategy, cache limits, timeout) lives in a separate file so it can
// be unit-tested; it is precached with the other modules and part of the cache hash.
sw.importScripts('assets/js/modules/sw-strategy.js');
const {
    chooseStrategy,
    evictionCount,
    runtimeCacheName,
    isCurrentCache,
    withTimeout,
    RUNTIME_CACHE_LIMIT,
    NETWORK_TIMEOUT_MS,
} = /** @type {any} */ (self).SwStrategy;
const RUNTIME_CACHE = runtimeCacheName(CACHE_NAME);

sw.addEventListener('install', (e) => {
    sw.skipWaiting();
    e.waitUntil(
        caches.open(CACHE_NAME).then((cache) => {
            return Promise.all(
                ASSETS.map((asset) => {
                    return fetch(new Request(asset, { cache: 'reload' }))
                        .then((response) => {
                            if (response.ok) {
                                return cache.put(asset, response);
                            }
                            throw new Error(`Response not OK for ${asset}`);
                        })
                        .catch((err) => {
                            console.warn(
                                `Failed to cache ${asset} with reload request, falling back to standard cache add:`,
                                err
                            );
                            return cache
                                .add(asset)
                                .catch((e) => console.error(`Standard cache fallback failed for ${asset}:`, e));
                        });
                })
            );
        })
    );
});

sw.addEventListener('activate', (e) => {
    e.waitUntil(
        caches
            .keys()
            .then((keys) =>
                Promise.all(keys.filter((key) => !isCurrentCache(key, CACHE_NAME)).map((key) => caches.delete(key)))
            )
            // Lets the browser start the page request while the worker boots (saves the startup delay).
            .then(() => sw.registration.navigationPreload && sw.registration.navigationPreload.enable())
            .then(() => sw.clients.claim())
    );
});

/**
 * Puts a response into the runtime cache and drops the oldest entries beyond the limit.
 * @param {Request} request
 * @param {Response} response
 */
async function putRuntime(request, response) {
    const cache = await caches.open(RUNTIME_CACHE);
    await cache.put(request, response);
    const keys = await cache.keys();
    const surplus = evictionCount(keys.length, RUNTIME_CACHE_LIMIT);
    await Promise.all(keys.slice(0, surplus).map((key) => cache.delete(key)));
}

/**
 * Offline answer for a page navigation: the cached page itself, then the same page without
 * its query string (projekt-detail.html?repo=... reads the query client-side, so one cached
 * copy serves every project), then the offline page. Always resolves to a real Response.
 * @param {Request} request
 */
async function offlineDocument(request) {
    return (
        (await caches.match(request)) ||
        (await caches.match(request, { ignoreSearch: true })) ||
        (await caches.match(OFFLINE_URL)) ||
        new Response('Offline', {
            status: 503,
            statusText: 'Offline and not yet cached',
            headers: { 'Content-Type': 'text/plain; charset=utf-8' },
        })
    );
}

sw.addEventListener('fetch', (e) => {
    const strategy = chooseStrategy({
        method: e.request.method,
        url: e.request.url,
        origin: sw.location.origin,
        accept: e.request.headers.get('accept') || '',
        hasRange: e.request.headers.has('range'),
        destination: e.request.destination,
    });
    if (strategy === 'bypass') return;

    if (strategy === 'network-first') {
        // The network answer (or the navigation preload) is cached for later. If it takes longer than
        // NETWORK_TIMEOUT_MS and a copy exists, the copy is served and the request keeps running.
        const network = Promise.resolve(e.preloadResponse)
            .then((preloaded) => preloaded || fetch(e.request))
            .then((networkResponse) => {
                if (networkResponse.status === 200) {
                    e.waitUntil(putRuntime(e.request, networkResponse.clone()));
                }
                return networkResponse;
            });
        network.catch(() => {}); // a late failure after the timeout must not surface as unhandled
        e.respondWith(
            caches
                .match(e.request, { ignoreSearch: true })
                .then((cached) => (cached ? withTimeout(network, NETWORK_TIMEOUT_MS, cached) : network))
                .catch(() => offlineDocument(e.request))
        );
        return;
    }

    // stale-while-revalidate for static assets (CSS, JS, fonts, images)
    e.respondWith(
        caches.match(e.request).then((cachedResponse) => {
            const fetchPromise = fetch(e.request)
                .then((networkResponse) => {
                    if (networkResponse.status === 200) {
                        e.waitUntil(putRuntime(e.request, networkResponse.clone()));
                    }
                    return networkResponse;
                })
                .catch(() => {
                    // Network failed (offline, blocked, timed out) and nothing was cached yet.
                    // Never resolve to `undefined` here - respondWith() requires a real Response,
                    // otherwise the browser reports the request itself as failed, which for a
                    // script/style file breaks the page's whole JS/CSS loading silently.
                    return new Response('', {
                        status: 503,
                        statusText: 'Offline and not yet cached',
                    });
                });

            return cachedResponse || fetchPromise;
        })
    );
});
